INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter dem BSI?', 2, '[{"text": "Cyber-Sicherheitsbehörde des Bundes", "correct": true, "because": "Schützt IT-Sicherheit"}, {"text": "Hardwareprüfstelle", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das BSI?', 3, '[{"text": "Informationssicherheit fördern", "correct": true, "because": "Schutz in Digitalisierung"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Software entwickeln", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben hat das BSI laut BSI-Gesetz?', 5, '[{"text": "IT-Sicherheitsstandards setzen", "correct": true, "because": "§ 8 BSIG"}, {"text": "Cyber-Bedrohungen abwehren", "correct": true, "because": "§ 5 BSIG"}, {"text": "Kritische Infrastrukturen schützen", "correct": true, "because": "§ 8a BSIG"}, {"text": "Marketing betreiben", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BSI ist dem Innenministerium unterstellt. b) Es ist nur für private Unternehmen zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Staat/Gesellschaft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim BSI?', 4, '[{"text": "IT-Sicherheitsvorschriften", "correct": false, "because": "Kernaufgabe"}, {"text": "Cyber-Bedrohungslage", "correct": false, "because": "Analyse wichtig"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das BSI kritische Infrastrukturen schützt?', 2, '[{"text": "Ja", "correct": true, "because": "§ 8a BSIG"}, {"text": "Nein", "correct": false, "because": "Gesetzliche Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Aufgaben des BSI?', 3, '[{"text": "BSI-Gesetz", "correct": true, "because": "Rechtliche Grundlage"}, {"text": "ArbZG", "correct": false, "because": "Arbeitszeitgesetz"}, {"text": "BGB", "correct": false, "because": "Bürgerliches Gesetzbuch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu den Aufgaben des BSI?', 5, '[{"text": "Warnungen vor Sicherheitslücken", "correct": true, "because": "§ 7 BSIG"}, {"text": "Mindeststandards für IT-Sicherheit", "correct": true, "because": "§ 8 BSIG"}, {"text": "Cyber-Angriffe abwehren", "correct": true, "because": "§ 5 BSIG"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das BSI schützt die IT des Bundes. b) Es ist nur für Hardware zuständig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Software"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim BSI unwichtig?', 4, '[{"text": "Cyber-Sicherheitsstrategie", "correct": false, "because": "Kernaufgabe"}, {"text": "Bedrohungserkennung", "correct": false, "because": "Wichtig"}, {"text": "Farbe der Büromöbel", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss das BSI Unternehmen bei IT-Sicherheit unterstützen?', 2, '[{"text": "Nein", "correct": true, "because": "Auf Ersuchen"}, {"text": "Ja", "correct": false, "because": "Freiwillig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das BSI für die IT-Sicherheit?', 4, '[{"text": "Früherkennung von Bedrohungen", "correct": true, "because": "§ 5 BSIG"}, {"text": "Sicherheitsstandards setzen", "correct": true, "because": "§ 8 BSIG"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das BSI nur für den Staat arbeitet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Wirtschaft/Gesellschaft"}, {"text": "Ja", "correct": false, "because": "Breiter Auftrag"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiert das BSI?', 3, '[{"text": "Cyber-Sicherheit", "correct": true, "because": "Hauptaufgabe"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BSI warnt vor Cyber-Bedrohungen. b) Es betreibt nur Forschung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Praxis"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein fehlender Schutz durch das BSI?', 5, '[{"text": "Erhöhte Cyber-Risiken", "correct": true, "because": "Weniger Abwehr"}, {"text": "Schwache Standards", "correct": true, "because": "Keine Vorgaben"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker beim BSI?', 3, '[{"text": "IT-Sicherheitsmaßnahmen umsetzen", "correct": true, "because": "Praxisbezug"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das BSI Warnungen herausgeben?', 2, '[{"text": "Ja", "correct": true, "because": "§ 7 BSIG"}, {"text": "Nein", "correct": false, "because": "Gesetzlich erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte das BSI für Bedrohungsanalysen nutzen?', 4, '[{"text": "Wireshark", "correct": true, "because": "Netzwerkanalyse"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
